-- 1: houyi-ceramic-ring
UPDATE products SET
  name = 'HOUYI حلقات السيراميك البيولوجية - مساحة سطح فائقة المسامية',
  description = E'حلقات سيراميك بيولوجية ذات هيكل مسامي مجهري يوفر مساحة سطح هائلة (~500 متر مربع/لتر) لاستعمار مليارات البكتيريا النافعة. تحوّل الأمونيا والنيتريت السامة إلى مواد آمنة.\n\nالمسام المفتوحة تسمح بتدفق الأوكسجين والماء عبر الحلقات لتغذية البكتيريا باستمرار. pH محايد تماماً لا يؤثر على كيمياء الماء.\n\nتدوم لسنوات طويلة وتحتاج فقط شطفاً خفيفاً بماء الحوض بشكل دوري. مناسبة لجميع أنواع الفلاتر الخارجية والداخلية.',
  specifications = '{"brand":"HOUYI","model":"Ceramic Ring","benefits":["مساحة سطحية هائلة (~500m²/L) لاستعمار البكتيريا","مسام مفتوحة لتدفق الأكسجين والماء","pH محايد تماماً لا يؤثر على كيمياء الماء","تدوم لسنوات بدون حاجة للاستبدال","تحوّل الأمونيا والنيتريت لمواد آمنة","مناسبة لجميع أنواع الفلاتر"],"المادة":"Sintered Glass/Ceramic","الشكل":"حلقات (Rings)","المسامية":"عالية (Microporous)","مناسب لـ":"فلاتر خارجية، داخلية، سومب","بلد المنشأ":"الصين","طريقة الاستخدام":"اغسل بماء نظيف لإزالة الغبار. ضع في حجرة الترشيح البيولوجي. لا تغسل أبداً بماء الحنفية - استخدم ماء الحوض فقط عند التنظيف.","تحذيرات":"لا تستخدم ماء الحنفية للتنظيف لأن الكلور يقتل البكتيريا النافعة. استبدل ربع الكمية فقط كل سنة."}'::jsonb
WHERE id = 'houyi-ceramic-ring';

-- 2: houyi-activated-carbon
UPDATE products SET
  name = 'HOUYI الكربون النشط عالي الامتصاص - مزيل السموم والألوان',
  description = E'كربون نشط عالي الجودة من الفحم القاري (Bituminous Coal) بقدرة امتصاص ممتازة (Iodine Number أعلى من 900). يمتص الأدوية والروائح والألوان الذائبة في الماء.\n\nحبيبات منخفضة الغبار لا تعكّر الماء عند الاستخدام. يُستخدم للترشيح الكيميائي لإزالة المواد المذابة التي لا يستطيع الفلتر الميكانيكي إزالتها.\n\nمثالي لإزالة اصفرار الماء الناتج عن الأخشاب الطبيعية أو لإزالة بقايا الأدوية بعد انتهاء دورة العلاج.',
  specifications = '{"brand":"HOUYI","model":"Activated Carbon","benefits":["قدرة امتصاص عالية (Iodine Number >900)","يزيل الروائح الكريهة واصفرار الماء","يمتص بقايا الأدوية بعد العلاج","حبيبات منخفضة الغبار لا تعكّر الماء","يعيد شفافية الماء الكريستالية","ترشيح كيميائي يكمل الترشيح الميكانيكي"],"المادة":"Bituminous Coal Based","الشكل":"Pellets / Granules","النشاط":"Iodine Number > 900","النوع":"Chemical Filtration","مناسب لـ":"جميع أنواع الفلاتر، إزالة أدوية، إزالة اصفرار","بلد المنشأ":"الصين","طريقة الاستخدام":"ضع الكربون في كيس شبكي. اغسله تحت الماء الجاري لإزالة الغبار. ضعه في حجرة الترشيح الكيميائي. استبدله كل 4-6 أسابيع.","تحذيرات":"أزل الكربون أثناء العلاج بالأدوية لأنه يمتصها. استبدله بانتظام - الكربون المشبع يطلق السموم مرة أخرى."}'::jsonb
WHERE id = 'houyi-activated-carbon';

-- 3: houyi-white-cotton
UPDATE products SET
  name = 'HOUYI قطن الفلتر الأبيض الناعم - ترشيح ميكانيكي أساسي',
  description = E'قطن ترشيح ميكانيكي أبيض ناعم يحتجز الجزيئات والأوساخ العالقة في الماء. يُوضع كأول طبقة في نظام الترشيح لحماية مواد الترشيح البيولوجية من الانسداد.\n\nكثافة مثالية تحقق التوازن بين فعالية الترشيح وتدفق الماء. يمكن قصّه بأي شكل ليناسب حجم الفلتر.\n\nاقتصادي ويمكن غسله وإعادة استخدامه عدة مرات قبل الاستبدال.',
  specifications = '{"brand":"HOUYI","model":"White Filter Cotton","benefits":["ترشيح ميكانيكي فعّال للجزيئات والأوساخ","يحمي مواد الترشيح البيولوجية من الانسداد","كثافة مثالية للتوازن بين الترشيح والتدفق","قابل للقص ليناسب أي فلتر","اقتصادي وقابل لإعادة الاستخدام","ماء أصفى بشكل ملحوظ"],"النوع":"ترشيح ميكانيكي","اللون":"أبيض","الكثافة":"ناعمة","مناسب لـ":"جميع أنواع الفلاتر","بلد المنشأ":"الصين","طريقة الاستخدام":"قص القطن بحجم حجرة الفلتر. ضعه كأول طبقة (قبل مواد الترشيح البيولوجية). اغسله بماء الحوض أسبوعياً. استبدله عندما يفقد شكله.","تحذيرات":"لا تضغط القطن بإحكام - يعيق تدفق الماء. استبدله كل 2-4 أسابيع حسب حمل الحوض."}'::jsonb
WHERE id = 'houyi-white-cotton';

-- 4: houyi-medium-cotton-brown
UPDATE products SET
  name = 'HOUYI قطن الفلتر البني متوسط الكثافة - ترشيح ثنائي | 50 جم',
  description = E'قطن ترشيح بني بكثافة متوسطة يوفر ترشيحاً ميكانيكياً وبيولوجياً معاً. الألياف الأكثر كثافة تحتجز جزيئات أدقّ مع السماح لنمو البكتيريا النافعة على سطحها.\n\nيُوضع كطبقة ثانية بعد القطن الأبيض الناعم وقبل وسائط الترشيح البيولوجية. عبوة 50 جم مسبقة القطع تناسب الفلاتر الصغيرة والمتوسطة.\n\nمناسب لتحسين صفاء الماء في الأحواض التي تعاني من تعكّر مستمر رغم وجود قطن أبيض.',
  specifications = '{"brand":"HOUYI","model":"Brown Filter Cotton","benefits":["كثافة متوسطة للترشيح الميكانيكي والبيولوجي","يحتجز جزيئات أدقّ من القطن الأبيض","يوفر سطحاً لنمو البكتيريا النافعة","عبوة 50 جم مسبقة القطع","يحسّن صفاء الماء بشكل ملحوظ","يعمل كطبقة وسيطة في نظام الترشيح"],"الوزن":"50 جم","النوع":"ترشيح ميكانيكي/بيولوجي","اللون":"بني","الكثافة":"متوسطة","مناسب لـ":"فلاتر صغيرة ومتوسطة، تحسين صفاء الماء","بلد المنشأ":"الصين","طريقة الاستخدام":"ضعه بعد القطن الأبيض وقبل السيراميك. اغسله بماء الحوض كل أسبوعين. لا تغسله بماء الحنفية للحفاظ على البكتيريا.","تحذيرات":"لا تستبدله مع القطن الأبيض في نفس الوقت - استبدلهما بالتناوب. لا تعصره بقوة عند الغسيل."}'::jsonb
WHERE id = 'houyi-medium-cotton-brown';

-- 5: houyi-net-bag
UPDATE products SET
  name = 'HOUYI أكياس الميديا الشبكية بسحّاب آمن - لتنظيم مواد الفلتر',
  description = E'أكياس شبكية بسحّاب محكم مصممة لحفظ وتنظيم مواد الترشيح داخل الفلتر. تمنع انتشار الكربون النشط والبيو بول والمواد الصغيرة في الحوض.\n\nالشبكة تسمح بتدفق الماء بحرية عبر المواد المحفوظة بداخلها. السحّاب الآمن يمنع الانفتاح العرضي أثناء تدفق الماء القوي.\n\nقابلة للغسيل وإعادة الاستخدام لفترات طويلة. تسهّل عملية استبدال مواد الترشيح - فقط أخرج الكيس واستبدل المحتوى.',
  specifications = '{"brand":"HOUYI","model":"Media Net Bag","benefits":["سحّاب آمن لا ينفتح مع تدفق الماء","شبكة تسمح بتدفق الماء بحرية","تمنع انتشار مواد الترشيح الصغيرة","قابلة للغسيل وإعادة الاستخدام","تسهّل استبدال مواد الترشيح","تنظّم حجرات الفلتر بكفاءة"],"المادة":"نايلون شبكي متين","الإغلاق":"سحّاب (Zipper)","مناسب لـ":"الكربون النشط، البيو بول، حلقات السيراميك الصغيرة","بلد المنشأ":"الصين","طريقة الاستخدام":"املأ الكيس بمادة الترشيح (لا تملأه بالكامل - اترك مساحة). أغلق السحّاب بإحكام. ضع الكيس في حجرة الفلتر.","تحذيرات":"لا تملأ الكيس أكثر من 75% لتسمح بتدفق الماء. تحقق من إغلاق السحّاب بعد كل صيانة."}'::jsonb
WHERE id = 'houyi-net-bag';

-- 6: houyi-dophin-skimmer
UPDATE products SET
  name = 'HOUYI سكيمر السطح الكهربائي DoPhin - إزالة الطبقة الزيتية',
  description = E'سكيمر كهربائي لإزالة الطبقة الزيتية والشوائب العائمة على سطح ماء الحوض. يسحب طبقة السطح ويمررها عبر فلتر داخلي ثم يعيد الماء نظيفاً.\n\nالطبقة الزيتية تشكل حاجزاً يمنع تبادل الأوكسجين بين الماء والهواء. إزالتها تحسّن مستوى الأوكسجين المذاب وتسمح لضوء الإضاءة بالوصول للنباتات.\n\nتشغيل صامت واستهلاك كهرباء منخفض. مناسب للأحواض المزروعة وأحواض الأسماك الاستوائية.',
  specifications = '{"brand":"DoPhin / HOUYI","model":"Surface Skimmer","benefits":["إزالة فورية للطبقة الزيتية من سطح الماء","يحسّن مستوى الأوكسجين المذاب","تشغيل صامت واستهلاك منخفض","فلتر داخلي يحتجز الشوائب","يسمح للضوء بالوصول للنباتات","سطح ماء صافٍ وكريستالي"],"النوع":"سكيمر سطحي كهربائي","مناسب لـ":"أحواض النباتات، الأحواض الاستوائية","بلد المنشأ":"الصين","طريقة الاستخدام":"ثبّت الجهاز على حافة الحوض بحيث يكون مدخل الشفط عند مستوى سطح الماء. نظّف الإسفنجة الداخلية أسبوعياً.","تحذيرات":"حافظ على مستوى الماء ثابتاً. نظّف الإسفنجة بانتظام لمنع انسداد التدفق."}'::jsonb
WHERE id = 'houyi-dophin-skimmer';

-- 7: houyi-oxygenation-tube
UPDATE products SET
  name = 'HOUYI أنبوب أكسجين سيليكوني مرن - لا يتصلب | قياسي 4 ملم',
  description = E'أنبوب هواء مصنوع من السيليكون المرن عالي الجودة بقطر داخلي 4 ملم. يتميز بمرونته الدائمة التي لا تتأثر بمرور الوقت على عكس الأنابيب البلاستيكية التي تتصلب وتنكسر.\n\nشفاف ومقاوم للاصفرار والأشعة فوق البنفسجية. يتحمل الثني المتكرر دون أن ينسد أو يقطع تدفق الهواء.\n\nمتوافق مع جميع مضخات الهواء وأحجار الهواء والملحقات ذات القطر القياسي 4 ملم.',
  specifications = '{"brand":"HOUYI","model":"Silicone Air Tube","benefits":["سيليكون مرن لا يتصلب مع الوقت","شفاف ومقاوم للاصفرار","يتحمل الثني دون انسداد","مقاوم للأشعة فوق البنفسجية","متوافق مع جميع المضخات القياسية","يدوم أطول من الأنابيب البلاستيكية"],"المادة":"سيليكون مرن","القطر":"4 ملم (قياسي)","مناسب لـ":"مضخات الهواء، أحجار الهواء، الفلاتر الإسفنجية","بلد المنشأ":"الصين","طريقة الاستخدام":"قص بالطول المناسب. وصّل طرفاً بمضخة الهواء والآخر بحجر الهواء. استخدم صمام عدم رجوع بين المضخة والحوض.","تحذيرات":"استخدم صمام عدم رجوع لمنع رجوع الماء عند انقطاع الكهرباء. تأكد من عدم وجود ثنيات تعيق التدفق."}'::jsonb
WHERE id = 'houyi-oxygenation-tube';

-- 8: houyi-check-valve
UPDATE products SET
  name = 'HOUYI صمام عدم رجوع للهواء - حماية المضخة من الماء',
  description = E'صمام أمان يُركّب على خرطوم الهواء بين مضخة الهواء والحوض. يسمح بمرور الهواء باتجاه واحد فقط (نحو الحوض) ويمنع رجوع الماء نحو المضخة عند انقطاع الكهرباء.\n\nبدون هذا الصمام، عند انقطاع الكهرباء يرجع الماء عبر خرطوم الهواء ويتلف المضخة أو يسبب فيضاناً إذا كانت المضخة أسفل مستوى الحوض.\n\nسهل التركيب - فقط اقطع خرطوم الهواء وأدخل الصمام. تأكد من اتجاه السهم نحو الحوض.',
  specifications = '{"brand":"HOUYI","model":"Check Valve","benefits":["يمنع رجوع الماء نحو المضخة","يحمي المضخة من التلف","يمنع الفيضان عند انقطاع الكهرباء","سهل التركيب على خرطوم الهواء","تدفق هواء سلس باتجاه واحد","ضروري لكل نظام تهوية"],"المادة":"Plastic / Membrane","الوظيفة":"One-way Flow (تدفق باتجاه واحد)","القطر":"4 ملم (قياسي)","مناسب لـ":"جميع مضخات الهواء، خراطيم 4 ملم","بلد المنشأ":"الصين","طريقة الاستخدام":"اقطع خرطوم الهواء. أدخل الصمام بحيث يكون السهم باتجاه الحوض. تأكد من الإحكام. ركّبه فوق مستوى الماء لأفضل حماية.","تحذيرات":"تأكد من اتجاه السهم - التركيب المعكوس يمنع وصول الهواء. استبدله سنوياً لضمان الأداء. تحقق من عدم وجود تسريب."}'::jsonb
WHERE id = 'houyi-check-valve';

-- 9: houyi-air-distributor-4port
UPDATE products SET
  name = 'HOUYI موزع هواء 4 مخارج - مع صمامات تحكم فردية',
  description = E'موزع هواء يقسم خرج مضخة هواء واحدة إلى 4 مخارج منفصلة. كل مخرج مزود بصمام تحكم فردي لضبط كمية الهواء المتدفقة لكل حجر هواء أو فلتر.\n\nيوفر عليك شراء 4 مضخات منفصلة - مضخة واحدة قوية كافية لتشغيل 4 أحجار هواء أو فلاتر إسفنجية عبر هذا الموزع.\n\nالصمامات الدوارة تسمح بالتحكم الدقيق في كمية الهواء لكل مخرج حسب الحاجة. يمكن إغلاق أي مخرج لا يُستخدم بالكامل.',
  specifications = '{"brand":"HOUYI","model":"Air Distributor 4-Port","benefits":["4 مخارج منفصلة من مضخة واحدة","صمام تحكم فردي لكل مخرج","يوفر شراء مضخات متعددة","تحكم دقيق بكمية الهواء لكل مخرج","يمكن إغلاق المخارج غير المستخدمة","متوافق مع خراطيم 4 ملم القياسية"],"المخارج":"4 مخارج","التحكم":"صمامات فردية دوارة","القطر":"4 ملم (قياسي)","مناسب لـ":"توزيع الهواء على عدة أحواض أو أحجار هواء","بلد المنشأ":"الصين","طريقة الاستخدام":"وصّل المدخل بمضخة الهواء عبر خرطوم. وصّل كل مخرج بخرطوم يذهب لحجر هواء أو فلتر. اضبط الصمامات للتحكم بالتدفق.","تحذيرات":"تأكد من أن مضخة الهواء قوية كفاية لتشغيل 4 مخارج. أغلق المخارج غير المستخدمة لتجنب فقدان ضغط الهواء."}'::jsonb
WHERE id = 'houyi-air-distributor-4port';

-- 10: houyi-connector-i-4mm
UPDATE products SET
  name = 'HOUYI وصلات خراطيم الهواء على شكل I - 4 ملم | عبوة متعددة',
  description = E'وصلات بلاستيكية على شكل حرف I لربط خرطومي هواء بقطر 4 ملم معاً. حل بسيط وفعّال لتمديد طول الخرطوم أو إصلاح خرطوم مقطوع.\n\nتصميم محكم يمنع تسرب الهواء من نقطة الوصل. مادة بلاستيكية متينة لا تتفاعل مع الماء ولا تتأثر بالرطوبة.\n\nعبوة متعددة القطع تكفي لعدة استخدامات وإصلاحات.',
  specifications = '{"brand":"HOUYI","model":"I-Connector 4mm","benefits":["ربط محكم لخرطومي هواء معاً","يمدد طول الخرطوم بسهولة","يصلح الخراطيم المقطوعة","لا تسريب للهواء من نقطة الوصل","بلاستيك متين لا يتفاعل مع الماء","عبوة متعددة القطع اقتصادية"],"المادة":"بلاستيك متين","القطر":"4 ملم","الشكل":"I-Shape (مستقيم)","مناسب لـ":"خراطيم هواء 4 ملم القياسية","بلد المنشأ":"الصين","طريقة الاستخدام":"ادفع طرف الخرطوم على أحد جانبي الوصلة. ادفع الخرطوم الثاني على الجانب الآخر. تأكد من الإحكام.","تحذيرات":"تأكد من مطابقة القطر (4 ملم). ادفع الخرطوم بقوة كافية لمنع الانفلات. استبدل إذا أصبحت رخوة."}'::jsonb
WHERE id = 'houyi-connector-i-4mm';
